const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The analysis is global. A specific geometry is not needed for a global reduction.
  const year1 = 2003;
  const year2 = 2019;

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/006/MCD12Q1');

  const image1 = collection.filterDate(ee.Date(year1 + '-01-01'), ee.Date(year1 + '-12-31')).first();
  const image2 = collection.filterDate(ee.Date(year2 + '-01-01'), ee.Date(year2 + '-12-31')).first();

  // Directly check if images are valid objects. getInfo() on null will fail.
  const image1Exists = ee.Algorithms.IsEqual(image1, null).not();
  const image2Exists = ee.Algorithms.IsEqual(image2, null).not();

  if (!image1Exists.getInfo() || !image2Exists.getInfo()) {
      console.log(`Data missing for one or both years: ${year1}, ${year2}.`);
      console.log('A');
      return;
  }

  const landCoverBand = 'LC_Type1';
  // IGBP classification: 12=Croplands, 14=Cropland/Natural Vegetation Mosaic
  const cropClasses = [12, 14];

  // 3. Processing
  // Create a binary mask for crop areas for each year.
  const cropMask1 = image1.select(landCoverBand).eq(cropClasses[0]).or(image1.select(landCoverBand).eq(cropClasses[1]));
  const cropMask2 = image2.select(landCoverBand).eq(cropClasses[0]).or(image2.select(landCoverBand).eq(cropClasses[1]));

  // Create an image representing the area of each pixel in square kilometers.
  const pixelArea = ee.Image.pixelArea().divide(1000 * 1000); // to sq km

  // Multiply the binary mask by the pixel area to get the crop area per pixel.
  const cropAreaImage1 = cropMask1.multiply(pixelArea);
  const cropAreaImage2 = cropMask2.multiply(pixelArea);

  // 4. Calculation
  // Sum the areas globally. Use a large scale to prevent timeout on global calculations.
  const reducer = ee.Reducer.sum();
  const scale = 5000; // 5km scale for global reduction

  const totalCropArea1Dict = cropAreaImage1.reduceRegion({
    reducer: reducer,
    scale: scale,
    maxPixels: 1e13
  });

  const totalCropArea2Dict = cropAreaImage2.reduceRegion({
    reducer: reducer,
    scale: scale,
    maxPixels: 1e13
  });

  const area1 = totalCropArea1Dict.get(landCoverBand).getInfo();
  const area2 = totalCropArea2Dict.get(landCoverBand).getInfo();

  // 5. Validation & Final Answer
  if (area1 === null || area2 === null || area1 === 0 || area2 === 0) {
      console.log('Calculation failed: one or both area calculations returned null or zero.');
      console.log('C3');
      return;
  }

  const percentageIncrease = ((area2 - area1) / area1) * 100;

  console.log(`Global Crop Area ${year1} (million sq km): ${(area1 / 1e6).toFixed(2)}`);
  console.log(`Global Crop Area ${year2} (million sq km): ${(area2 / 1e6).toFixed(2)}`);
  console.log(`Percentage Increase: ${percentageIncrease.toFixed(2)}%`);

  if (percentageIncrease >= 5) {
      console.log('A');
  } else {
      console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred: ', err);
    console.log('D');
});
